@* Popup with common emoji options *@

<div class="emoji-picker">
    @foreach (var emoji in _emojis)
    {
        <button class="emoji-btn" @onclick="() => SelectEmoji(emoji)" title="@emoji">@emoji</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] _emojis = ["👍", "❤️", "😂", "🎉", "😮", "🙏"];

    private async Task SelectEmoji(string emoji)
    {
        await OnEmojiSelected.InvokeAsync(emoji);
    }
}

@* Single message with reactions and hover actions *@

<div class="message-item @(IsThreadStarter ? "thread-starter" : "")" @onmouseenter="ShowActions" @onmouseleave="HideActions">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (IsThreadStarter)
    {
        <button class="thread-link" @onclick="OpenThread">
            @ReplyCount replies
        </button>
    }

    @if (_showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="OpenThread" title="Reply in thread">💬 Reply</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">😀 React</button>
        </div>
    }

    @if (_showEmojiPicker)
    {
        <EmojiPicker OnEmojiSelected="HandleReaction" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Message Message { get; set; } = default!;

    [Parameter]
    public bool IsThreadStarter { get; set; }

    [Parameter]
    public int ReplyCount { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _showActions;
    private bool _showEmojiPicker;

    private void ShowActions() => _showActions = true;

    private void HideActions()
    {
        _showActions = false;
        _showEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private async Task OpenThread()
    {
        await OnOpenThread.InvokeAsync(Message.Id);
    }

    private async Task HandleReaction(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@* Left sidebar showing list of channels *@

<div class="channel-list">
    <h3 class="channel-list-header">Channels</h3>
    @foreach (var channel in Channels)
    {
        <div class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
             @onclick="() => SelectChannel(channel)">
            <div class="channel-name"># @channel.Name</div>
            <div class="channel-description">@Truncate(channel.Description, 40)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int SelectedChannelId { get; set; }

    [Parameter]
    public EventCallback<Channel> OnChannelSelected { get; set; }

    private async Task SelectChannel(Channel channel)
    {
        await OnChannelSelected.InvokeAsync(channel);
    }

    private static string Truncate(string text, int maxLength)
    {
        if (string.IsNullOrEmpty(text) || text.Length <= maxLength)
            return text;
        return text[..maxLength] + "…";
    }
}

@* Main message area: channel header, scrollable message list, input *@

<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         IsThreadStarter="ThreadSummaries.ContainsKey(message.Id)"
                         ReplyCount="ThreadSummaries.GetValueOrDefault(message.Id)?.ReplyCount ?? 0"
                         OnOpenThread="HandleOpenThread"
                         OnReact="HandleReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input"
                  @bind="NewMessageContent"
                  @bind:event="oninput"
                  placeholder="Message #@Channel.Name"
                  @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(NewMessageContent)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Channel Channel { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private string NewMessageContent { get; set; } = "";
    private bool _loadingMore;

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(NewMessageContent)) return;
        var content = NewMessageContent;
        NewMessageContent = "";
        await OnSendMessage.InvokeAsync(content);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers load more (JS interop would provide exact scroll position;
        // here we expose the callback for the parent to handle pagination)
    }

    private async Task HandleOpenThread(int messageId)
    {
        await OnOpenThread.InvokeAsync(messageId);
    }

    private async Task HandleReact((int MessageId, string Emoji) args)
    {
        await OnReact.InvokeAsync(args);
    }

    public async Task RequestLoadMore()
    {
        if (_loadingMore) return;
        _loadingMore = true;
        StateHasChanged();
        await OnLoadMore.InvokeAsync();
        _loadingMore = false;
        StateHasChanged();
    }
}

@* Right panel showing thread replies for a root message *@

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="Close" title="Close thread">✕</button>
    </div>

    <div class="thread-root-message">
        <span class="message-author">@RootMessage.Author</span>
        <p class="message-content">@RootMessage.Content</p>
    </div>

    <div class="thread-replies">
        @if (Loading)
        {
            <div class="loading-indicator">Loading thread…</div>
        }
        else
        {
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        }
    </div>

    <div class="thread-input-area">
        <textarea class="message-input"
                  @bind="ReplyContent"
                  @bind:event="oninput"
                  placeholder="Reply in thread…"
                  @onkeydown="HandleKeyDown"></textarea>
        <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(ReplyContent)">
            Reply
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Message RootMessage { get; set; } = default!;

    [Parameter]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public bool Loading { get; set; }

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnReply { get; set; }

    private string ReplyContent { get; set; } = "";

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(ReplyContent)) return;
        var content = ReplyContent;
        ReplyContent = "";
        await OnReply.InvokeAsync(content);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendReply();
        }
    }

    private async Task Close()
    {
        await OnClose.InvokeAsync();
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

