toolArgs.file_text:
/* Chat page layout */
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

/* Channel sidebar */
.channel-list {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
}

.channel-list-header {
    padding: 1rem;
    margin: 0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    position: relative;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 9px;
    padding: 1px 6px;
    min-width: 18px;
    text-align: center;
}

/* Message area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
}

.chat-layout.thread-open .message-area {
    max-width: 55%;
}

.message-area.empty-state {
    align-items: center;
    justify-content: center;
    color: #949ba4;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #949ba4;
    font-size: 0.85rem;
}

/* Message item */
.message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-item:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

.message-content {
    margin-top: 0.25rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #3f4248;
    border: 1px solid #4e5058;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: default;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Hover action buttons */
.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
}

.action-btn:hover {
    background: #404249;
    color: #fff;
}

/* Emoji picker */
.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 4px;
    display: flex;
    gap: 2px;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
    cursor: pointer;
}

.emoji-btn:hover {
    background: #404249;
}

/* Message input */
.message-input-area,
.thread-input-area {
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #dbdee1;
    padding: 0.6rem 1rem;
    font-size: 0.9rem;
    resize: none;
    min-height: 2.5rem;
    max-height: 8rem;
    font-family: inherit;
}

.message-input:focus {
    outline: none;
    box-shadow: 0 0 0 1px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.6rem 1.2rem;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #dbdee1;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
}

.thread-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #404249;
    color: #fff;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #2e3035;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #b5bac1;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

